     type V = UpoolView;

     closed spec fn view(&self) -> UpoolView {
         UpoolView {
             allocated_frames: Set::new(|addr: int|
                 exists|i: int|
                     #[trigger] self.bitmap@.set_bits.contains(i)
                     && addr == frame_addr_of(i)
