         assert forall|addr: int| self@.free_frames.contains(addr) implies addr >= 0
         by {
             let i = choose|i: int| self.bitmap@.is_covered(i) && !self.bitmap@.set_bits.contains(i) && addr == frame_addr_of(i);
             assert(i >= 0);
             assert(addr == i * ps);
