         bitmap.chunk_count(),
     );

     // SAFETY: single-threaded boot; no other reference to `INSTANCE` exists.
     unsafe { INSTANCE.write(Inner { bitmap }) };
     INSTANCE_INIT.store(true, ORDER);
     Ok(())
 }

